# Generated by the release's package publish; edits here are replaced by the next release.
class Wsb < Formula
  desc "Workspace tools for git across submodules, version stamping, GitHub, and the workbench"
  homepage "https://github.com/jowharshamshiri/wsb"
  version "1.666.27449"
  license "Apache-2.0"

  on_macos do
    url "https://releases.bahramj.com/wsb/release/1.666.27449/wsb-1.666.27449-darwin-arm64.tar.gz"
    sha256 "644d66780d1bc622fe8cbaeea9737aa7dee065b69ac3f1365f61d09a88df27de"
  end

  on_linux do
    if Hardware::CPU.arm?
      odie "wsb 1.666.27449: no linux-arm64 build"
    else
      url "https://releases.bahramj.com/wsb/release/1.666.27449/wsb-1.666.27449-linux-x86_64.tar.gz"
      sha256 "792f98a03c6f9e4c1ed8b5809a93289f66594edd393c9c7a91ad79d11ef37a82"
    end
  end

  def install
    # The archive extracts to wsb/{wsb,wsb-daemon,wsb-claude,LICENSE,NOTICE,
    # THIRD-PARTY-NOTICES}, and Homebrew runs this from inside that one directory. The three
    # programs stay together: wsb starts wsb-daemon from its own directory.
    libexec.install Dir["*"]
    # Says that Homebrew installed this wsb, by the path that outlives each version (opt, not the
    # Cellar): `wsb upgrade` leaves it to Homebrew, names the command that upgrades it, and brings
    # the workshop over once Homebrew has.
    (libexec/"wsb-installed-by.json").write <<~WSB_INSTALLED_BY
      {"format": 1, "manager": "Homebrew", "program": "#{opt_libexec}/wsb", "update": "brew upgrade wsb"}
    WSB_INSTALLED_BY
    bin.install_symlink libexec/"wsb"
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/wsb --version")
  end
end

